// TÀI KHOẢN MASTER CỐ ĐỊNH CỦA BẠN
const MASTER_EMAILS = ["teacher@gmail.com", "nhanthu262n@gmail.com"];
const GOOGLE_CLIENT_ID = "897241491720-obod7unscrt6m0drrv6msjp1jscu32gu.apps.googleusercontent.com";

firebase.initializeApp(firebaseConfig);
const auth = firebase.auth();
const db = firebase.firestore();
const offlineAuth = auth;
const offlineDb = db;
const offlineCloud = { firestore: { FieldValue: firebase.firestore.FieldValue } };

let CURRENT_USER = null;
let USER_ROLE = "student";
const TEST_OPEN_ACCESS = false;

// Auth state is authoritative. Complete the UI from Firebase immediately;
// profile Firestore enrichment is best-effort and must never block login.
function authWithTimeout(promise, ms = 7000, code = "AUTH_TIMEOUT") {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => {
      const error = new Error(code);
      error.code = code;
      reject(error);
    }, ms))
  ]);
}
function completeLoginSafely(user) {
  if (typeof completeLogin === "function") {
    completeLogin(user);
  } else {
    window.__PANDAHAN_PENDING_AUTH_USER = user;
    window.dispatchEvent(new CustomEvent("pandahan-auth-pending"));
  }
}
auth.onAuthStateChanged(async (user) => {
  if (!user) {
    CURRENT_USER = null;
    window.__PANDAHAN_AUTH_STATE_RESOLVED = true;
    const appEl = document.getElementById("app");
    const overlay = document.getElementById("proAuthOverlay");
    if (appEl) appEl.style.display = "none";
    if (overlay) overlay.style.display = "flex";
    return;
  }

  const fallbackRole = MASTER_EMAILS.includes((user.email || "").toLowerCase()) ? "teacher" : "student";
  const baseUser = {
    ...user,
    uid: user.uid,
    email: user.email || "",
    name: user.displayName || "Học viên",
    displayName: user.displayName || "Học viên",
    role: fallbackRole,
    status: "approved"
  };
  CURRENT_USER = baseUser;
  USER_ROLE = fallbackRole;
  completeLoginSafely(baseUser);
  window.__PANDAHAN_AUTH_STATE_RESOLVED = true;

  // Firestore profile is enrichment only. A slow/offline/denied profile read
  // must not leave a successfully authenticated user behind the login overlay.
  try {
    const ref = db.collection("users").doc(user.uid);
    const snap = await authWithTimeout(ref.get());
    let userData = snap.exists ? snap.data() : null;
    if (!userData) {
      userData = { uid: user.uid, email: user.email || "", name: user.displayName || "Học viên", displayName: user.displayName || "Học viên", role: fallbackRole, status: "approved", createdAt: new Date() };
      ref.set({ ...userData, lastSeen: new Date(), updatedAt: new Date() }, { merge: true }).catch((error) => console.warn("Profile create deferred:", error.message || error));
    }
    CURRENT_USER = { ...CURRENT_USER, ...userData, uid: user.uid, email: user.email || userData.email || "" };
    USER_ROLE = CURRENT_USER.role || fallbackRole;
    if (typeof applyRoleUI === "function") applyRoleUI();
  } catch (e) {
    console.warn("Auth profile enrichment skipped:", e.message || e);
  }
});

let googleLoginInFlight = false;
function isMobileAuthContext() {
  const ua = navigator.userAgent || "";
  return /Android|iPhone|iPad|iPod|Windows Phone|Mobile/i.test(ua)
    || (window.matchMedia && window.matchMedia("(max-width: 768px)").matches)
    || (navigator.maxTouchPoints > 1 && window.innerWidth <= 900);
}
function setGoogleAuthBusy(busy, message = "") {
  googleLoginInFlight = !!busy;
  const indicator = document.getElementById("loadingIndicator");
  const googleBox = document.getElementById("fbGoogleBtnPro");
  const submit = document.querySelector("#proAuthOverlay .btn-main");
  const fallback = document.getElementById("proGoogleFallbackBtn");
  if (indicator) { indicator.textContent = message || "⌛ Đang xử lý, vui lòng chờ..."; indicator.style.display = busy ? "block" : "none"; }
  if (googleBox) { googleBox.style.opacity = busy ? "0.62" : "1"; googleBox.style.pointerEvents = busy ? "none" : "auto"; googleBox.setAttribute("aria-busy", busy ? "true" : "false"); }
  if (fallback) { fallback.disabled = !!busy; fallback.style.opacity = busy ? "0.62" : "1"; fallback.setAttribute("aria-busy", busy ? "true" : "false"); }
  if (submit) submit.disabled = !!busy;
}
function showGoogleAuthError(error) {
  const code = String(error?.code || "");
  const messages = {
    "auth/unauthorized-domain": "Tên miền hiện tại chưa được thêm vào Firebase Authentication → Authorized domains.",
    "auth/popup-blocked": "Trình duyệt đã chặn cửa sổ Google. Hãy bấm lại hoặc dùng luồng chuyển trang Google.",
    "auth/popup-closed-by-user": "Bạn đã đóng cửa sổ Google trước khi hoàn tất đăng nhập.",
    "auth/cancelled-popup-request": "Đang có một yêu cầu Google khác. Vui lòng chờ rồi thử lại.",
    "auth/network-request-failed": "Không kết nối được mạng. Vui lòng kiểm tra mạng rồi thử lại.",
    "auth/web-storage-unsupported": "Trình duyệt điện thoại đang chặn bộ nhớ đăng nhập. Hãy tắt chế độ ẩn danh/chặn cookie rồi thử lại.",
    "auth/invalid-api-key": "Firebase API key không hợp lệ trên bản đang chạy. Hãy tải lại đúng bản GitHub Pages mới.",
    "AUTH_PERSISTENCE_TIMEOUT": "Bộ nhớ đăng nhập phản hồi quá lâu. Đã hủy trạng thái treo; hãy thử lại hoặc dùng email/mật khẩu.",
    "AUTH_REDIRECT_TIMEOUT": "Không chuyển được tới Google sau 12 giây. Hãy kiểm tra mạng, tắt chặn popup/cookie rồi thử lại.",
    "AUTH_POPUP_TIMEOUT": "Cửa sổ Google không trả kết quả sau 45 giây. Hãy cho phép popup/cookie rồi thử lại.",
    "AUTH_REDIRECT_RESULT_TIMEOUT": "Google đã trở về nhưng phản hồi đăng nhập không tới được web. Hãy tải lại trang và thử lại.",
    "AUTH_NO_REDIRECT_USER": "Google đã trở về nhưng chưa tạo được phiên Firebase. Hãy thử lại bằng nút Google hoặc kiểm tra Authorized domains."
  };
  const el = document.getElementById("proError");
  if (el) { el.textContent = messages[code] || ("Lỗi Google: " + (error?.message || "Không xác định")); el.style.display = "block"; }
}
function setGoogleFallbackVisible(visible) {
  const button = document.getElementById("proGoogleFallbackBtn");
  if (button) button.style.display = visible ? "flex" : "none";
}
function initGoogleSignIn() {
  if (typeof google === "undefined" || !google.accounts?.id) { setGoogleFallbackVisible(true); return; }
  const container = document.getElementById("fbGoogleBtnPro");
  if (!container || !GOOGLE_CLIENT_ID) { setGoogleFallbackVisible(true); return; }
  if (isMobileAuthContext()) {
    container.innerHTML = "";
    container.style.display = "none";
    setGoogleFallbackVisible(true);
    return;
  }
  container.style.display = "flex";
  try { google.accounts.id.initialize({
    client_id: GOOGLE_CLIENT_ID,
    ux_mode: "popup",
    callback: async (res) => {
      if (googleLoginInFlight) return;
      setGoogleAuthBusy(true, "⌛ Đang xác thực tài khoản Google...");
      try {
        const cred = firebase.auth.GoogleAuthProvider.credential(res.credential);
        await auth.setPersistence(firebase.auth.Auth.Persistence.LOCAL);
        await auth.signInWithCredential(cred);
      } catch (e) {
        console.error("Google Auth Error:", e); showGoogleAuthError(e);
      } finally { setGoogleAuthBusy(false); }
    }
  });
    const width = Math.min(400, Math.max(220, Math.floor(container.clientWidth || 280)));
    container.innerHTML = "";
    google.accounts.id.renderButton(container, { theme: "outline", size: "large", shape: "pill", width });
    setGoogleFallbackVisible(false);
  } catch (error) {
    console.warn("Google Identity Services unavailable:", error);
    setGoogleFallbackVisible(true);
  }
}
async function proGoogleLogin() {
  if (googleLoginInFlight) return;
  setGoogleAuthBusy(true, isMobileAuthContext() ? "⌛ Đang chuyển tới Google..." : "⌛ Đang mở Google...");
  const provider = new firebase.auth.GoogleAuthProvider();
  provider.setCustomParameters({ prompt: "select_account" });
  try { await authWithTimeout(auth.setPersistence(firebase.auth.Auth.Persistence.LOCAL), 3500, "AUTH_PERSISTENCE_TIMEOUT"); }
  catch (persistenceError) { console.warn("Google persistence unavailable; continue with Firebase default:", persistenceError.message || persistenceError); }
  try {
    // Popup returns the credential directly and is more reliable on Android
    // browsers that lose Firebase redirect state across a GitHub Pages path.
    // Redirect remains a fallback when popup is blocked/unsupported.
    await authWithTimeout(auth.signInWithPopup(provider), 45000, "AUTH_POPUP_TIMEOUT");
    return;
  } catch (error) {
    console.warn("Google popup/redirect error:", error);
    const code = String(error?.code || "");
    const redirectFallbackCodes = ["auth/popup-blocked", "auth/operation-not-supported-in-this-environment", "auth/web-storage-unsupported", "AUTH_POPUP_TIMEOUT"];
    if (redirectFallbackCodes.includes(code)) {
      try { sessionStorage.setItem("pandahan_google_redirect_pending", "1"); } catch (_) {}
      try { await authWithTimeout(auth.signInWithRedirect(provider), 12000, "AUTH_REDIRECT_TIMEOUT"); return; } catch (redirectError) { showGoogleAuthError(redirectError); }
    } else showGoogleAuthError(error);
  } finally { setGoogleAuthBusy(false); }
}

async function proLogin() {
  const email = document.getElementById("proEmail").value;
  const pass = document.getElementById("proPass").value;
  const errEl = document.getElementById("proError");
  if (!email || !pass) {
    if (errEl) { errEl.textContent = "Vui lòng nhập đầy đủ email và mật khẩu."; errEl.style.display = "block"; }
    return;
  }
  try {
    await auth.signInWithEmailAndPassword(email, pass);
    if (errEl) errEl.style.display = "none";
  } catch (e) {
    if (errEl) { errEl.textContent = "Lỗi: " + e.message; errEl.style.display = "block"; }
  }
}

function closeProAuth() {
  const overlay = document.getElementById('proAuthOverlay');
  const appEl = document.getElementById('app');
  if (overlay) overlay.style.display = "none";
  if (appEl) appEl.style.display = "block";
}

function handleRedirectResult() {
  let pending = false;
  try { pending = sessionStorage.getItem("pandahan_google_redirect_pending") === "1"; } catch (_) {}
  if (pending) setGoogleAuthBusy(true, "⌛ Đang hoàn tất đăng nhập Google...");
  authWithTimeout(auth.getRedirectResult(), 15000, "AUTH_REDIRECT_RESULT_TIMEOUT").then((result) => {
    if (result.user) console.log("Đăng nhập thành công sau redirect");
    else if (pending && !auth.currentUser) {
      const error = new Error("AUTH_NO_REDIRECT_USER");
      error.code = "AUTH_NO_REDIRECT_USER";
      throw error;
    }
  }).catch((error) => {
    if (String(error?.code || "") !== "auth/no-auth-event") showGoogleAuthError(error);
  }).finally(() => {
    if (pending) { try { sessionStorage.removeItem("pandahan_google_redirect_pending"); } catch (_) {} }
    if (pending) setGoogleAuthBusy(false);
  });
  if (pending) window.setTimeout(() => {
    if (googleLoginInFlight) {
      try { sessionStorage.removeItem("pandahan_google_redirect_pending"); } catch (_) {}
      setGoogleAuthBusy(false);
      showGoogleAuthError({ code: "AUTH_REDIRECT_RESULT_TIMEOUT" });
    }
  }, 16000);
}
window.addEventListener('load', () => {
  handleRedirectResult();
  window.setTimeout(() => { if (!CURRENT_USER) initGoogleSignIn(); }, 700);
});
async function handleLogin() {
  const email = document.getElementById("loginEmail").value;
  const pass = document.getElementById("loginPassword").value;
  let targetEmail = email === "teacher" ? "teacher@gmail.com" : email;
  try { await auth.signInWithEmailAndPassword(targetEmail, pass); }
  catch (e) {
    const el = document.getElementById("authError");
    if (el) { el.textContent = "Lỗi: " + e.message; el.style.display = "block"; }
  }
}

