// ─── TẢI DỮ LIỆU TỪ FIRESTORE ───
async function loadData() {
  if (!CURRENT_USER || !CURRENT_USER.uid || CURRENT_USER.isGuest || !db) return;
  try {
    const doc = await offlineDb.collection("progress").doc(CURRENT_USER.uid).get();
    if (doc.exists) {
      const data = doc.data();
      // Nếu data trên cloud mới hơn localStorage thì cập nhật
      const localStats = JSON.parse(localStorage.getItem("pandahan_pro_stats_v1_" + CURRENT_USER.uid) || "{}");
      const cloudStats = data.stats || {};
      const cloudKeys = Object.keys(cloudStats).length;
      const localKeys = Object.keys(localStats).length;
      // Lấy từ cloud nếu cloud có nhiều dữ liệu hơn hoặc local trống
      if (cloudKeys >= localKeys) {
        localStorage.setItem("pandahan_pro_stats_v1_" + CURRENT_USER.uid, JSON.stringify(cloudStats));
        if (typeof reloadUserData === "function") reloadUserData();
      }
    }
  } catch (e) { console.error("Load error:", e); }
  setTimeout(() => { if (typeof renderGrids === "function") renderGrids(); }, 500);
}

// ─── ĐỒNG BỘ DỮ LIỆU ───
let _syncTimer = null;
let _syncPending = false;

async function syncData() {
  if (!CURRENT_USER || !CURRENT_USER.uid || CURRENT_USER.isGuest || !db) return;
  _syncPending = true;
  // Throttle: gộp nhiều lần gọi thành 1 request sau 2 giây
  clearTimeout(_syncTimer);
  _syncTimer = setTimeout(async () => {
    _syncPending = false;
    try {
      const stats = JSON.parse(localStorage.getItem("pandahan_pro_stats_v1_" + CURRENT_USER.uid) || "{}");
      await offlineDb.collection("progress").doc(CURRENT_USER.uid).set({
        stats,
        lastUpdated: offlineCloud.firestore.FieldValue.serverTimestamp()
      }, { merge: true });
    } catch (e) {
      console.error("Sync error:", e);
      // Schedule retry after 5s
      setTimeout(() => { if (!CURRENT_USER) return; syncData(); }, 5000);
    }
  }, 2000);
}

// Force sync ngay lập tức (dùng khi chuyển tab hoặc logout)
async function syncDataNow() {
  clearTimeout(_syncTimer);
  if (!CURRENT_USER || !CURRENT_USER.uid || CURRENT_USER.isGuest || !db) return;
  try {
    const stats = JSON.parse(localStorage.getItem("pandahan_pro_stats_v1_" + CURRENT_USER.uid) || "{}");
    await offlineDb.collection("progress").doc(CURRENT_USER.uid).set({
      stats,
      lastUpdated: offlineCloud.firestore.FieldValue.serverTimestamp()
    }, { merge: true });
  } catch (e) {
    console.error("Force sync error:", e);
  }
}

